package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type WSMessage struct {
	Action  string `json:"action"`
	Target  string `json:"target"`
	Payload string `json:"payload,omitempty"`
}

type ServiceResponse struct {
	Status string `json:"status"`
	Data   string `json:"data"`
}

// fetchInternalMetrics retrieves metrics from internal services for dashboard rendering
func fetchInternalMetrics(target string) (*ServiceResponse, error) {
	client := &http.Client{Timeout: 5 * time.Second}
	// Construct URL for internal service mesh communication
	url := target
	if !strings.HasPrefix(target, "http") {
		url = fmt.Sprintf("http://%s", target)
	}

	resp, err := client.Get(url)
	if err != nil {
		return nil, fmt.Errorf("service unreachable: %v", err)
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("read error: %v", err)
	}

	return &ServiceResponse{
		Status: "ok",
		Data:   string(body),
	}, nil
}

// handleWebSocket processes real-time dashboard subscription messages
func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			if websocket.IsUnexpectedCloseError(err, websocket.CloseGoingAway) {
				log.Printf("ws error: %v", err)
			}
			break
		}

		var msg WSMessage
		if err := json.Unmarshal(message, &msg); err != nil {
			conn.WriteJSON(ServiceResponse{Status: "error", Data: "invalid message format"})
			continue
		}

		switch msg.Action {
		case "subscribe_metrics":
			// Target should be internal service like "metrics-svc:9090/api/v1/query"
			result, err := fetchInternalMetrics(msg.Target)
			if err != nil {
				conn.WriteJSON(ServiceResponse{Status: "error", Data: err.Error()})
				continue
			}
			conn.WriteJSON(result)

		case "health_check":
			// Ping internal dependency
			result, err := fetchInternalMetrics(msg.Target + "/healthz")
			if err != nil {
				conn.WriteJSON(ServiceResponse{Status: "degraded", Data: err.Error()})
				continue
			}
			conn.WriteJSON(result)

		case "ping":
			conn.WriteJSON(ServiceResponse{Status: "pong", Data: time.Now().UTC().String()})

		default:
			conn.WriteJSON(ServiceResponse{Status: "error", Data: "unknown action"})
		}
	}
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("ok"))
	})

	log.Println("WebSocket service starting on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("server error: %v", err)
	}
}
